SELECT 
  FROM generation_jobs
 WHERE idempotency_key = #{idempotencyKey}

   AND requested_by_user_id = #{ownerId}

SELECT FROM generation_jobs WHERE (idempotency_key = #{baseIdempotencyKey} OR idempotency_key LIKE CONCAT(#{baseIdempotencyKey}, ':retry:%'))
AND requested_by_user_id = #{ownerId}
ORDER BY created_at DESC, id DESC LIMIT 1
